URL='http://are-sidecar:8000/mcp'
session=None

def req(payload):
    global session
    headers={'Content-Type':'application/json','Accept':'application/json, text/event-stream'}
    if session: headers['Mcp-Session-Id']=session
    r=urllib.request.Request(URL, data=json.dumps(payload).encode(), headers=headers, method='POST')
    with urllib.request.urlopen(r, timeout=60) as resp:
        if resp.headers.get('Mcp-Session-Id'): session=resp.headers.get('Mcp-Session-Id')
        body=resp.read().decode(); ct=resp.headers.get('Content-Type','')
    if ct.startswith('text/event-stream') or body.startswith('data:') or body.startswith('event:'):
        lines=[line[5:].strip() for line in body.splitlines() if line.startswith('data:')]
        body='\n'.join(lines) if lines else body
    if not body.strip(): return None
    return json.loads(body)

def init():
    req({'jsonrpc':'2.0','id':1,'method':'initialize','params':{'protocolVersion':'2024-11-05','capabilities':{},'clientInfo':{'name':'terminal-agent','version':'1.0'}}})
    try: req({'jsonrpc':'2.0','method':'notifications/initialized','params':{}})
    except Exception: pass

def call(name,args=None,id=10):
    return req({'jsonrpc':'2.0','id':id,'method':'tools/call','params':{'name':name,'arguments':args or {}}})

def unwrap(res):
    try:
        txt=res['result']['content'][0]['text']
        return json.loads(txt)
    except Exception:
        return res

if __name__=='__main__':
    init()
    for i, spec in enumerate(sys.argv[1:], start=10):
        if ':' in spec:
            name, argstr = spec.split(':',1)
            args=json.loads(argstr) if argstr else {}
        else:
            name=spec; args={}
        print('###', name)
        print(json.dumps(unwrap(call(name,args,i)), indent=2, ensure_ascii=False))
