    else:
        inner=data
    apts=inner['result'] if 'result' in inner else inner
    if isinstance(apts, dict) and 'apartments' in apts: apts=apts['apartments']
    return apts

def infer_city(loc, zip_code=''):
    # Prefer city immediately following postal code if present
    if zip_code:
        m=re.search(r'\b'+re.escape(str(zip_code))+r'\s+([^,]+)', loc)
        if m:
            return m.group(1).strip()
    m=re.search(r'\b\d{4}\s+([^,]+)', loc)
    if m: return m.group(1).strip()
    # If comma tail has postal code + city
    parts=[p.strip() for p in loc.split(',')]
    for p in reversed(parts):
        m=re.search(r'\b\d{4}\s+(.+)$', p)
        if m: return m.group(1).strip()
    return parts[-1].strip()

