        if val is None:
            # nested dict/list search
            def walk(x):
                if isinstance(x, dict):
                    for kk,vv in x.items():
                        if 'violent' in str(kk).lower() and isinstance(vv,(int,float)):
                            return vv
                        got=walk(vv)
                        if got is not None: return got
                elif isinstance(x, list):
                    for y in x:
                        got=walk(y)
                        if got is not None: return got
                return None
            val=walk(res)
